SELECT USER,HOST,ERROR_NUMBER,ERROR_NAME,SQL_STATE,SUM_ERROR_RAISED,SUM_ERROR_HANDLED,FIRST_SEEN,LAST_SEEN FROM performance_schema.events_errors_summary_by_account_by_error WHERE USER='ct_dev' AND SUM_ERROR_RAISED>0 ORDER BY LAST_SEEN DESC LIMIT 30;
SELECT MYSQL_ERRNO,RETURNED_SQLSTATE,MESSAGE_TEXT,LEFT(SQL_TEXT,140),EVENT_ID FROM performance_schema.events_statements_history_long WHERE MYSQL_ERRNO<>0 ORDER BY TIMER_START DESC LIMIT 20;
SELECT COUNT(*) AS history_rows FROM performance_schema.events_statements_history_long;
